module tb_TopModule;
    logic [99:0] a;
    logic [99:0] b;
    logic        sel;
    logic [99:0] out;

    TopModule dut (
        .a(a),
        .b(b),
        .sel(sel),
        .out(out)
    );

    initial begin
        // Test case 1
        a = 100'h1234567890abcdef12345678;
        b = 100'hfedcba0987654321fedcba09;
        sel = 0;
        #10;
        if (out !== a) begin
            $display("SELFTEST FAIL: sel=0, expected a=%h, got %h", a, out);
            $finish;
        end

        // Test case 2
        sel = 1;
        #10;
        if (out !== b) begin
            $display("SELFTEST FAIL: sel=1, expected b=%h, got %h", b, out);
            $finish;
        end

        // Test case 3
        a = 100'hffffffffffffffffffffffff;
        b = 100'h00000000000000000000;
        sel = 0;
        #10;
        if (out !== a) begin
            $display("SELFTEST FAIL: sel=0, expected a=%h, got %h", a, out);
            $finish;
        end

        sel = 1;
        #10;
        if (out !== b) begin
            $display("SELFTEST FAIL: sel=1, expected b=%h, got %h", b, out);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
